        if facts is not None:
            body["facts"] = dict(facts)
        if slots is not None:
            body["slots"] = dict(slots)
        if labels:
            body["labels"] = dict(labels)
        if context is not None:
            body["context"] = context
        if url is not None:
            body["url"] = url
        if category is not None:
            body["category"] = category
